#include <iostream>
#include <string>
#include <vector>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    vector<vector<int>> g(n);
    for (int i = 0; i < m; i++) {
        int a, b;
        cin >> a >> b;
        g[a].push_back(b);
        g[b].push_back(a);
    }
    vector<int> blocked(n, -1), cnt(n, 0), touched;
    string out;
    for (int y = 0; y < n; y++) {
        blocked[y] = y;  // y itself and its friends are not candidates
        for (int f : g[y]) blocked[f] = y;
        touched.clear();
        // Count mutual friends through every two-step path y - f - x.
        for (int f : g[y])
            for (int x : g[f])
                if (blocked[x] != y) {
                    if (cnt[x] == 0) touched.push_back(x);
                    cnt[x]++;
                }
        int pick = -1;
        if (!touched.empty()) {
            for (int x : touched)
                if (pick < 0 || cnt[x] > cnt[pick] || (cnt[x] == cnt[pick] && x < pick)) pick = x;
            for (int x : touched) cnt[x] = 0;
        } else {
            // Every candidate has 0 mutual friends: take the smallest allowed number.
            int x = 0;
            while (x < n && blocked[x] == y) x++;
            pick = x < n ? x : -1;
        }
        if (y) out += ' ';
        out += to_string(pick);
    }
    out += '\n';
    cout << out;
}

import java.io.*;
import java.util.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    public static void main(String[] args) throws IOException {
        int n = (int) nextLong(), m = (int) nextLong();
        int[] ea = new int[m], eb = new int[m], deg = new int[n + 1];
        for (int i = 0; i < m; i++) {
            ea[i] = (int) nextLong();
            eb[i] = (int) nextLong();
            deg[ea[i] + 1]++;
            deg[eb[i] + 1]++;
        }
        for (int i = 0; i < n; i++) deg[i + 1] += deg[i];
        int[] pos = Arrays.copyOf(deg, n), adj = new int[2 * m];
        for (int i = 0; i < m; i++) {
            adj[pos[ea[i]]++] = eb[i];
            adj[pos[eb[i]]++] = ea[i];
        }
        int[] blocked = new int[n], cnt = new int[n], touched = new int[n];
        Arrays.fill(blocked, -1);
        StringBuilder out = new StringBuilder();
        for (int y = 0; y < n; y++) {
            blocked[y] = y;  // y itself and its friends are not candidates
            for (int e = deg[y]; e < deg[y + 1]; e++) blocked[adj[e]] = y;
            int t = 0;
            // Count mutual friends through every two-step path y - f - x.
            for (int e = deg[y]; e < deg[y + 1]; e++) {
                int f = adj[e];
                for (int g = deg[f]; g < deg[f + 1]; g++) {
                    int x = adj[g];
                    if (blocked[x] != y) {
                        if (cnt[x] == 0) touched[t++] = x;
                        cnt[x]++;
                    }
                }
            }
            int pick = -1;
            if (t > 0) {
                for (int i = 0; i < t; i++) {
                    int x = touched[i];
                    if (pick < 0 || cnt[x] > cnt[pick] || (cnt[x] == cnt[pick] && x < pick)) pick = x;
                }
                for (int i = 0; i < t; i++) cnt[touched[i]] = 0;
            } else {
                // Every candidate has 0 mutual friends: take the smallest allowed number.
                int x = 0;
                while (x < n && blocked[x] == y) x++;
                pick = x < n ? x : -1;
            }
            if (y > 0) out.append(' ');
            out.append(pick);
        }
        System.out.println(out);
    }
}

package main

import (
	"io"
	"os"
	"strconv"
)

var data []byte
var pos int

func nextInt() int64 {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n, m := int(nextInt()), int(nextInt())
	g := make([][]int32, n)
	for i := 0; i < m; i++ {
		a, b := int32(nextInt()), int32(nextInt())
		g[a] = append(g[a], b)
		g[b] = append(g[b], a)
	}
	blocked, cnt := make([]int, n), make([]int, n)
	for i := range blocked {
		blocked[i] = -1
	}
	touched := []int32{}
	out := []byte{}
	for y := 0; y < n; y++ {
		blocked[y] = y // y itself and its friends are not candidates
		for _, f := range g[y] {
			blocked[f] = y
		}
		touched = touched[:0]
		// Count mutual friends through every two-step path y - f - x.
		for _, f := range g[y] {
			for _, x := range g[f] {
				if blocked[x] != y {
					if cnt[x] == 0 {
						touched = append(touched, x)
					}
					cnt[x]++
				}
			}
		}
		pick := -1
		if len(touched) > 0 {
			for _, x32 := range touched {
				x := int(x32)
				if pick < 0 || cnt[x] > cnt[pick] || (cnt[x] == cnt[pick] && x < pick) {
					pick = x
				}
			}
			for _, x := range touched {
				cnt[x] = 0
			}
		} else {
			// Every candidate has 0 mutual friends: take the smallest allowed number.
			x := 0
			for x < n && blocked[x] == y {
				x++
			}
			if x < n {
				pick = x
			}
		}
		if y > 0 {
			out = append(out, ' ')
		}
		out = strconv.AppendInt(out, int64(pick), 10)
	}
	out = append(out, '\n')
	os.Stdout.Write(out)
}
